527	// Shared drain tail: capture the (pre-execution) state, report `resume_pc`
528	// as the vsim resume point, and exit 200.
529	static void handoff_drain(unsigned int vcpu_idx, uint64_t resume_pc)
530	{
531	    drain_state_to_file(vcpu_idx, resume_pc, outfile_path);
532	    // 200 == kExitHandoffToQemu in the vsim repo's src/hybrid/exit_codes.hpp.
533	    // Distinguishes drain from workload completion (0) so the orchestrator
534	    // can decide the next spawn.
535	    exit(200);
536	}
