563	// Per-insn tick for oracle exit-drain mode. udata is this insn's HandoffSite.
564	// When armed (the exit boundary's own tick ran), this tick fires before its
565	// insn executes, so a drain here records the post-retire state of the
566	// boundary insn with pc = the dynamically-next insn's vaddr.
567	static void on_oracle_tick(unsigned int vcpu_idx, void *udata)
568	{
569	    const HandoffSite *site = (const HandoffSite *) udata;
570	    if (oracle_armed
571	        && (!drain_pc_set || site->vaddr == drain_pc_arg)) {
572	        handoff_drain(vcpu_idx, site->vaddr);
573	    }
574	    if (exit_pc_mode ? (site->vaddr == exit_pc_arg)
575	                     : (site->kind == HYBRID_HANDOFF_EXIT)) {
576	        oracle_armed = 1;
577	    }
578	}
