580	static void vcpu_tb_trans(qemu_plugin_id_t id, struct qemu_plugin_tb *tb)
581	{
582	    (void) id;
583	    size_t n = qemu_plugin_tb_n_insns(tb);
584	
585	    for (size_t i = 0; i < n; i++) {
586	        struct qemu_plugin_insn *insn = qemu_plugin_tb_get_insn(tb, i);
587	
588	        // v6: CSR write-mask tracking, active in every trigger mode (the mode
589	        // branches below `continue`). Decoded once at translation; only an
590	        // instruction that writes a mask-governed CSR gets an exec callback
591	        // (the CSR address is a static field of the encoding), so this costs
592	        // nothing at execution time outside boot-style CSR setup code. No
593	        // compressed CSR instruction exists, so the size==4 gate is exact.
594	        if (qemu_plugin_insn_size(insn) == 4) {
595	            uint32_t w = 0;
596	            if (qemu_plugin_insn_data(insn, &w, sizeof(w)) == sizeof(w)) {
597	                const int slot = hybrid_wm_slot_for_insn(w);
598	                if (slot >= 0)
599	                    qemu_plugin_register_vcpu_insn_exec_cb(
600	                        insn, on_csr_write, QEMU_PLUGIN_CB_NO_REGS,
601	                        (void *) (uintptr_t) slot);
602	            }
603	        }
604	
605	        // Oracle exit-drain mode: exclusive with every other mode (enforced
606	        // at install), so it owns the insn's registration outright. The site
607	        // carries the marker kind so the tick can arm on the EXIT marker.
608	        if (exit_marker_mode || exit_pc_mode) {
609	            HandoffSite *site = g_new0(HandoffSite, 1);
610	            site->kind  = HYBRID_HANDOFF_NONE;
611	            site->vaddr = qemu_plugin_insn_vaddr(insn);
612	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
613	            if (exit_marker_mode && site->size == 4) {
614	                uint32_t raw = 0;
615	                if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) == sizeof(raw))
616	                    hybrid_match_handoff_insn(raw, &site->kind);
617	            }
618	            qemu_plugin_register_vcpu_insn_exec_cb(
619	                insn, on_oracle_tick, QEMU_PLUGIN_CB_R_REGS, site);
620	            continue;
621	        }
622	
623	        if (pc_mode) {
624	            // PC-trigger mode: vaddr-only match; the drain resumes AT the
625	            // boundary (on_handoff_boundary), so the insn size is recorded
626	            // only for completeness.
627	            if (qemu_plugin_insn_vaddr(insn) != enter_pc_arg) continue;
628	            HandoffSite *site = g_new0(HandoffSite, 1);
629	            site->kind  = HYBRID_HANDOFF_ENTER;
630	            site->vaddr = qemu_plugin_insn_vaddr(insn);
631	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
632	            qemu_plugin_register_vcpu_insn_exec_cb(
633	                insn, on_handoff_boundary, QEMU_PLUGIN_CB_R_REGS, site);
634	            continue;
635	        }
636	
637	        // Marker-trigger mode (default).
638	        // The markers are `slti x0, x0, 0x5A0/0x5A1`, always 32-bit
639	        // (sz==4): SLTI has no compressed form, so the sz!=4 skip is
640	        // exact, not an approximation.
641	        size_t sz = qemu_plugin_insn_size(insn);
642	        if (sz != 4) continue;
643	        uint32_t raw = 0;
644	        if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) != sizeof(raw))
645	            continue;
646	        hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
647	        if (!hybrid_match_handoff_insn(raw, &kind)) continue;
648	        HandoffSite *site = g_new0(HandoffSite, 1);
649	        site->kind  = kind;
650	        site->vaddr = qemu_plugin_insn_vaddr(insn);
651	        site->size  = (uint32_t) sz;
652	        qemu_plugin_register_vcpu_insn_exec_cb(
653	            insn, on_handoff, QEMU_PLUGIN_CB_R_REGS, site);
654	    }
655	}
