657	// Parse a `name=value` plugin arg's value as u64 (base auto-detected, so
658	// 0x-hex and decimal both work). Same accept/reject behavior as the previous
659	// per-option copies of this block. Returns 0 on success, -1 (after printing
660	// the standard invalid-arg line) on garbage.
661	static int parse_u64_arg(const char *name, const char *val, uint64_t *out)
662	{
663	    char *endp = NULL;
664	    unsigned long long v = g_ascii_strtoull(val, &endp, 0);
665	    if (!endp || *endp != '\0') {
666	        fprintf(stderr, "hybrid_handoff: invalid %s=%s\n", name, val);
667	        return -1;
668	    }
669	    *out = (uint64_t) v;
670	    return 0;
671	}
